        // Rack: no required parents, filter only by the ones already selected
        frm.set_query("rack", SE_LOCATION_TABLE, se_rack_query);

        register_se_location_events();
    }
});


// Builds the filter: every field in the list must already be chosen in the row,
// and the list shows only the records that belong to those values.
function se_location_query(required_fields) {
    return function (doc, cdt, cdn) {
        const row = locals[cdt][cdn];
        const filters = {};

        for (const fieldname of required_fields) {
            if (!row[fieldname]) {
                return {
                    filters: {
                        name: ["=", "__no_matching_location__"]
                    }
                };
            }

            filters[fieldname] = row[fieldname];
        }

        return { filters };
    };
}


// Rack list: narrow by any parent that is already selected (none are mandatory)
function se_rack_query(doc, cdt, cdn) {
    const row = locals[cdt][cdn];
    const filters = {};

    ["warehouse", "floor", "area", "shelf"].forEach(fieldname => {
        if (row[fieldname]) {
            filters[fieldname] = row[fieldname];
        }
    });

    return { filters };
}


function register_se_location_events() {
    const df = frappe.meta.get_docfield("Stock Entry", SE_LOCATION_TABLE);

    if (!df) {
        return;
    }

    window.__se_location_clear_registered = window.__se_location_clear_registered || {};

    if (window.__se_location_clear_registered[df.options]) {
        return;
    }

    window.__se_location_clear_registered[df.options] = true;

    frappe.ui.form.on(df.options, {
        warehouse(frm, cdt, cdn) {
            clear_se_location_fields(frm, cdt, cdn, ["floor", "area", "shelf", "rack"]);
        },

        floor(frm, cdt, cdn) {
            clear_se_location_fields(frm, cdt, cdn, ["area", "shelf", "rack"]);
        },

        area(frm, cdt, cdn) {
            clear_se_location_fields(frm, cdt, cdn, ["shelf", "rack"]);
        },

        shelf(frm, cdt, cdn) {
            clear_se_location_fields(frm, cdt, cdn, ["rack"]);
        },

        // Rack selected -> fill all parents
        rack(frm, cdt, cdn) {
            autofill_se_location_from_rack(frm, cdt, cdn);
        }
    });
}


// When a field changes, clear the fields below it.
function clear_se_location_fields(frm, cdt, cdn, fields) {
    if (frm.doctype !== "Stock Entry") {
        return;
    }

    // Skip while the rack is auto-filling the parents
    if (window.__se_location_autofilling) {
        return;
    }

    fields.forEach(fieldname => {
        const row = locals[cdt] && locals[cdt][cdn];

        if (row && row[fieldname]) {
            frappe.model.set_value(cdt, cdn, fieldname, "");
        }
    });
}


async function autofill_se_location_from_rack(frm, cdt, cdn) {
    if (frm.doctype !== "Stock Entry" || window.__se_location_autofilling) {
        return;
    }

    const first_row = locals[cdt] && locals[cdt][cdn];

    if (!first_row || !first_row.rack) {
        return;
    }

    const rack = first_row.rack;

    // Find the doctype that the "rack" link field points to
    const rack_df = frappe.meta.get_docfield(cdt, "rack");
    const rack_doctype = rack_df && rack_df.options;

    if (!rack_doctype) {
        return;
    }

    const r = await frappe.db.get_value(
        rack_doctype,
        rack,
        ["warehouse", "floor", "area", "shelf"]
    );

    const values = r && r.message;

    if (!values) {
        return;
    }

    // Turn the guard on and cancel any pending release from an earlier autofill
    window.__se_location_autofilling = true;
    clearTimeout(window.__se_location_release_timer);

    try {
        for (const fieldname of ["warehouse", "floor", "area", "shelf"]) {
            const row = locals[cdt] && locals[cdt][cdn];

            if (row && values[fieldname] && row[fieldname] !== values[fieldname]) {
                await frappe.model.set_value(cdt, cdn, fieldname, values[fieldname]);
            }
        }

        // If anything cleared the rack while the parents were being filled, put it back
        const row = locals[cdt] && locals[cdt][cdn];
        if (row && row.rack !== rack) {
            await frappe.model.set_value(cdt, cdn, "rack", rack);
        }
    } finally {
        // Keep the guard on a little longer so late-firing change handlers are still skipped.
        window.__se_location_release_timer = setTimeout(async () => {
            try {
                // Final safety check after everything has settled
                const row = locals[cdt] && locals[cdt][cdn];
                if (row && row.rack !== rack) {
                    await frappe.model.set_value(cdt, cdn, "rack", rack);
                }
            } finally {
                window.__se_location_autofilling = false;
            }
        }, SE_GUARD_RELEASE_DELAY);
    }
}

})();
