frappe.ui.form.on(RECOVERED_PARTS_DOCTYPE, {
    disposition(frm, cdt, cdn) {
        const row = locals[cdt][cdn];

        if (is_reusable(row)) {
            if (!row.destination_warehouse) {
                const warehouse = get_default_destination(frm, row);

                if (warehouse) {
                    frappe.model.set_value(
                        cdt, cdn, "destination_warehouse", warehouse
                    );
                }
            }
        } else if (row.disposition === "Scrap") {
            // Scrap destination is handled by the Python process.
            frappe.model.set_value(cdt, cdn, "destination_warehouse", "");
        }

        sync_reusable_parts(frm);
    },

    item_code(frm, cdt, cdn) {
        const row = locals[cdt][cdn];

        if (is_reusable(row) && !row.destination_warehouse) {
            const warehouse = get_default_destination(frm, row);

            if (warehouse) {
                frappe.model.set_value(
                    cdt, cdn, "destination_warehouse", warehouse
                );
            }
        }

        sync_reusable_parts(frm);
    },

    quantity(frm) {
        sync_reusable_parts(frm);
