function get_default_destination(frm, row) {
    // Only use a warehouse already recorded for this item.
    const existing = (frm.doc.storage_location || []).find(
        storage => storage.item === row.item_code && storage.warehouse
    );

    return existing ? existing.warehouse : "";
}


// ============================================================
// FILL MISSING DESTINATION WAREHOUSES
// ============================================================

function fill_missing_destinations(frm) {
    if (frm.doc.docstatus !== 0) {
        return;
    }

    (frm.doc.recovered_parts || []).forEach(row => {
        if (is_reusable(row) && row.item_code && !row.destination_warehouse) {
            row.destination_warehouse = get_default_destination(frm, row);
        }
    });

    frm.refresh_field("recovered_parts");
}


// ============================================================
// SYNCHRONIZE REUSABLE PARTS TO storage_location
// ============================================================

function sync_reusable_parts(frm) {
    // Do not modify submitted or cancelled documents.
    if (frm.doc.docstatus !== 0) {
        return;
    }

    const reusable_rows = (frm.doc.recovered_parts || []).filter(
        row => is_reusable(row) && row.item_code
    );

    const storage_rows = frm.doc.storage_location || [];

    // Preserve location details for existing item occurrences.
    const existing_by_item = {};

    storage_rows.forEach(row => {
        if (!row.item) {
            return;
        }

        if (!existing_by_item[row.item]) {
            existing_by_item[row.item] = [];
        }

        existing_by_item[row.item].push({
            warehouse: row.warehouse || "",
            floor: row.floor || "",
            area: row.area || "",
            shelf: row.shelf || "",
            rack: row.rack || "",
            uom: row.uom || "",
            quantity: row.quantity || 1
        });
    });

    // Count each item so duplicate items are supported.
    const desired_counts = {};
    const current_counts = {};

    reusable_rows.forEach(row => {
        desired_counts[row.item_code] =
            (desired_counts[row.item_code] || 0) + 1;
    });

    storage_rows.forEach(row => {
        if (row.item) {
            current_counts[row.item] =
                (current_counts[row.item] || 0) + 1;
        }
    });

    const same_items =
        JSON.stringify(sort_object(desired_counts)) ===
        JSON.stringify(sort_object(current_counts));

    // --------------------------------------------------------
    // CASE 1: The item rows already match.
    // Update quantities and destination warehouses in place.
    // --------------------------------------------------------

    if (same_items) {
        const occurrence = {};

        reusable_rows.forEach(row => {
            const item_code = row.item_code;

            occurrence[item_code] = occurrence[item_code] || 0;

            const matching_rows = storage_rows.filter(
                storage => storage.item === item_code
            );

            const storage = matching_rows[occurrence[item_code]];

            occurrence[item_code] += 1;

            if (!storage) {
                return;
            }

            const quantity = row.quantity || 1;

            if (Number(storage.quantity || 0) !== Number(quantity)) {
                frappe.model.set_value(
                    storage.doctype,
                    storage.name,
                    "quantity",
                    quantity
                );
            }

            if (
                row.destination_warehouse &&
                storage.warehouse !== row.destination_warehouse
            ) {
                frappe.model.set_value(
                    storage.doctype,
                    storage.name,
                    "warehouse",
                    row.destination_warehouse
                );
            }
        });

        frm.refresh_field("storage_location");
        return;
    }

    // --------------------------------------------------------
    // CASE 2: Item rows changed.
    // Rebuild the table and preserve matching location details.
    // --------------------------------------------------------

    frm.clear_table("storage_location");

    const occurrence = {};

    reusable_rows.forEach(row => {
        const item_code = row.item_code;

        occurrence[item_code] = occurrence[item_code] || 0;

        const old_rows = existing_by_item[item_code] || [];
        const old = old_rows[occurrence[item_code]] || {};

        occurrence[item_code] += 1;

        const storage = frm.add_child("storage_location");

        storage.item = item_code;
        storage.quantity = row.quantity || 1;

        storage.warehouse =
            row.destination_warehouse ||
            old.warehouse ||
            "";

        storage.floor = old.floor || "";
        storage.area = old.area || "";
        storage.shelf = old.shelf || "";
        storage.rack = old.rack || "";
        storage.uom = old.uom || "";
    });

    frm.refresh_field("storage_location");
}


// ============================================================
// SORT OBJECT KEYS FOR CONSISTENT COMPARISON
// ============================================================

function sort_object(obj) {
    const result = {};

    Object.keys(obj)
        .sort()
        .forEach(key => {
            result[key] = obj[key];
        });

    return result;
}


// Let other scripts or buttons call the sync after they load rows:
//   frm.refresh_field("recovered_parts");
//   window.sync_tear_down_storage(frm);
window.sync_tear_down_storage = sync_reusable_parts;

// Vehicle Tear Down: cascading location filters
// Warehouse -> Floor -> Area -> Shelf -> Rack
// Selecting a Rack auto-fills Warehouse, Floor, Area and Shelf

(function () {
    const PARENT_DOCTYPE = "Vehicle Tear Down";
    const CHILD_TABLE = "storage_location";
    const LOCATION_PARENTS = ["warehouse", "floor", "area", "shelf"];

    frappe.ui.form.on(PARENT_DOCTYPE, {
        setup(frm) {
            set_storage_location_filters(frm);
        },

        refresh(frm) {
            set_storage_location_filters(frm);
        }
    });

    function set_storage_location_filters(frm) {
        frm.set_query("floor", CHILD_TABLE, function (doc, cdt, cdn) {
            return build_location_filter(cdt, cdn, ["warehouse"]);
        });

        frm.set_query("area", CHILD_TABLE, function (doc, cdt, cdn) {
            return build_location_filter(cdt, cdn, ["warehouse", "floor"]);
        });

        frm.set_query("shelf", CHILD_TABLE, function (doc, cdt, cdn) {
            return build_location_filter(cdt, cdn, ["warehouse", "floor", "area"]);
        });

        // Rack: no required parents, filter only by the ones already selected
        frm.set_query("rack", CHILD_TABLE, function (doc, cdt, cdn) {
            const row = locals[cdt][cdn];
            const filters = {};

            LOCATION_PARENTS.forEach(fieldname => {
                if (row[fieldname]) {
                    filters[fieldname] = row[fieldname];
                }
            });

            return { filters };
        });
    }

    function build_location_filter(cdt, cdn, required_fields) {
        const row = locals[cdt][cdn];
        const filters = {};

        // Do not show any choices until all parent fields are selected.
        for (const fieldname of required_fields) {
            if (!row[fieldname]) {
                return {
                    filters: {
                        name: ["=", "__no_matching_location__"]
                    }
                };
            }

            filters[fieldname] = row[fieldname];
        }

        return { filters };
    }

    // Clear dependent location fields when a parent changes.
    frappe.ui.form.on("Storage Location", {
        warehouse(frm, cdt, cdn) {
            if (frm.doctype !== PARENT_DOCTYPE) return;

            clear_location_fields(cdt, cdn, ["floor", "area", "shelf", "rack"]);
        },

        floor(frm, cdt, cdn) {
            if (frm.doctype !== PARENT_DOCTYPE) return;

            clear_location_fields(cdt, cdn, ["area", "shelf", "rack"]);
        },

        area(frm, cdt, cdn) {
            if (frm.doctype !== PARENT_DOCTYPE) return;

            clear_location_fields(cdt, cdn, ["shelf", "rack"]);
        },

        shelf(frm, cdt, cdn) {
            if (frm.doctype !== PARENT_DOCTYPE) return;

            clear_location_fields(cdt, cdn, ["rack"]);
        },

        // Rack selected -> fill all parents
        rack(frm, cdt, cdn) {
            if (frm.doctype !== PARENT_DOCTYPE) return;

            autofill_location_from_rack(cdt, cdn);
        }
    });

    function clear_location_fields(cdt, cdn, fields) {
        // Skip while the rack is auto-filling the parents
        if (window.__vtd_location_autofilling) return;

        const row = locals[cdt][cdn];

        if (!row) return;

        fields.forEach(fieldname => {
            if (row[fieldname]) {
                frappe.model.set_value(cdt, cdn, fieldname, "");
            }
        });
    }

    async function autofill_location_from_rack(cdt, cdn) {
        if (window.__vtd_location_autofilling) return;

        const row = locals[cdt][cdn];

        if (!row || !row.rack) return;

        // Find the doctype that the "rack" link field points to
        const rack_df = frappe.meta.get_docfield(cdt, "rack");
        const rack_doctype = rack_df && rack_df.options;

        if (!rack_doctype) return;

        const r = await frappe.db.get_value(rack_doctype, row.rack, LOCATION_PARENTS);
        const values = r && r.message;

        if (!values) return;

        window.__vtd_location_autofilling = true;

        try {
            for (const fieldname of LOCATION_PARENTS) {
                if (values[fieldname] && row[fieldname] !== values[fieldname]) {
                    await frappe.model.set_value(cdt, cdn, fieldname, values[fieldname]);
                }
            }
        } finally {
            window.__vtd_location_autofilling = false;
        }
    }
})();

frappe.ui.form.on('Service Request', {
    vehicle_number: async function(frm) {

        // Clear existing values
        frm.set_value('item', '');
        frm.set_value('item_group', '');
        frm.set_value('brand', '');

        if (!frm.doc.vehicle_number) {
            return;
        }

        try {
            // Step 1: Fetch Item Code from Serial No
            let serial = await frappe.db.get_value(
                'Serial No',
                frm.doc.vehicle_number,
                'item_code'
            );

            if (!serial.message || !serial.message.item_code) {
                frappe.msgprint('Item not found for this Vehicle Number.');
                return;
            }

            let item_code = serial.message.item_code;

            // Step 2: Fetch Item Details
            let item = await frappe.db.get_value(
                'Item',
                item_code,
                ['item_group', 'brand']
            );

            if (item.message) {

                // Step 3: Populate Service Request
                await frm.set_value('item', item_code);

                await frm.set_value(
                    'item_group',
                    item.message.item_group || ''
                );

                await frm.set_value(
                    'brand',
                    item.message.brand || ''
                );

            }

        } catch (error) {
            console.error('Vehicle Details Fetch Error:', error);
            frappe.msgprint('Unable to fetch vehicle details.');
        }
    }
});

// Service Request: Create > Service Entry (only while no Service Entry exists)

const SERVICE_ENTRY = "Service Entry";
const BUTTON_LABEL = __("Service Entry");
const BUTTON_GROUP = __("Create");

// Service Request field -> Service Entry field (change if your fieldnames differ)
const FIELD_MAP = {
    vehicle_number: "vehicle_number",
    item: "item",
    item_group: "item_group",
    brand: "brand",
    complaint_type: "service_type"
};

// Link field on Service Entry that points back to the Service Request.
const REQUEST_LINK_FIELD = "service_id";

frappe.ui.form.on("Service Request", {
    async refresh(frm) {
        // Remove first so repeated refreshes never stack buttons.
        frm.remove_custom_button(BUTTON_LABEL, BUTTON_GROUP);

        // The request must be saved first.
        if (frm.is_new()) {
            return;
        }

        // A Service Entry (draft or submitted) already exists: no Create button.
        if (await service_entry_exists(frm)) {
            return;
        }

        frm.add_custom_button(
            BUTTON_LABEL,
            () => create_service_entry(frm),
            BUTTON_GROUP
        );
    }
});


async function service_entry_exists(frm) {
    try {
        const response = await frappe.db.get_value(
            SERVICE_ENTRY,
            { [REQUEST_LINK_FIELD]: frm.doc.name, docstatus: ["<", 2] },
            "name"
        );

        return Boolean(response.message && response.message.name);
    } catch (error) {
        console.error("Service Entry check failed:", error);
        return false;
    }
}


function create_service_entry(frm) {
    if (frm.is_dirty()) {
        frappe.msgprint(__("Please save the Service Request first."));
        return;
    }

    // Load the Service Entry doctype so we only fill fields that exist.
    frappe.model.with_doctype(SERVICE_ENTRY, () => {
        const has_field = fieldname =>
            Boolean(frappe.meta.get_docfield(SERVICE_ENTRY, fieldname));

        const values = {};

        Object.entries(FIELD_MAP).forEach(([source, target]) => {
            if (frm.doc[source] && has_field(target)) {
                values[target] = frm.doc[source];
            }
        });

        if (has_field(REQUEST_LINK_FIELD)) {
            values[REQUEST_LINK_FIELD] = frm.doc.name;
        }

        frappe.new_doc(SERVICE_ENTRY, values);
    });
}

// Service Entry: Submit only when the Service Status is Completed or Non-repairable

const SUBMIT_ALLOWED_STATUS = ["Completed", "Non-repairable"];

frappe.ui.form.on("Service Entry", {
    refresh(frm) {
        toggle_submit_button(frm);
    },

    service_status(frm) {
        toggle_submit_button(frm);
