frappe.ui.form.on('Service Entry', {
    setup(frm) {
        // Only show spares that belong to the selected vehicle's box items
        frm.set_query('item', 'serviced_items', function () {
            return {
                filters: {
                    name: ['in', frm._box_items || []]
                }
            };
        });

        // Set UOM when an item is picked in a serviced_items row
        const child_dt = frappe.meta.get_docfield('Service Entry', 'serviced_items').options;
        frappe.ui.form.on(child_dt, {
            item(frm, cdt, cdn) {
                set_row_uom(frm, cdt, cdn);
            }
        });
    },

    refresh(frm) {
        load_box_items(frm);
    },

    item(frm) {
        // Vehicle changed: reload the allowed spares and clear rows that are no longer valid
        load_box_items(frm).then(() => {
            (frm.doc.serviced_items || []).forEach(row => {
                if (row.item && !frm._box_items.includes(row.item)) {
                    frappe.model.set_value(row.doctype, row.name, 'item', null);
                }
            });
        });
    }
});

function load_box_items(frm) {
    frm._box_rows = [];
    frm._box_items = [];
    if (!frm.doc.item) return Promise.resolve();

    return frappe.db.get_doc('Item', frm.doc.item).then(doc => {
        frm._box_rows = doc.custom_box_items || [];
        frm._box_items = frm._box_rows
            .map(r => r.item || r.item_code)
            .filter(Boolean);
    });
}

function set_row_uom(frm, cdt, cdn) {
    const row = locals[cdt][cdn];

    if (!row.item) {
        frappe.model.set_value(cdt, cdn, 'uom', null);
        return;
    }

    // 1) Use the UOM defined in the vehicle's box items (Inside Items) if present
    const box_row = (frm._box_rows || []).find(r => (r.item || r.item_code) === row.item);
    if (box_row && box_row.uom) {
        frappe.model.set_value(cdt, cdn, 'uom', box_row.uom);
        return;
    }

    // 2) Otherwise fall back to the item's stock UOM
    frappe.db.get_value('Item', row.item, 'stock_uom').then(r => {
        frappe.model.set_value(cdt, cdn, 'uom', r.message.stock_uom);
    });
}

