// collect items matched by custom_supplier OR by the Supplier Items table
function load_supplier_items(frm) {
    frm._supplier_items = null;

    if (!frm.doc.supplier) {
        set_supplier_item_query(frm);
        return;
    }

    const supplier = frm.doc.supplier;

    const by_field = frappe.xcall('frappe.client.get_list', {
        doctype: 'Item',
        fields: ['name'],
        filters: { custom_supplier: supplier },
        limit_page_length: 0
    });

    const by_table = frappe.xcall('frappe.client.get_list', {
        doctype: 'Item Supplier',
        parent: 'Item',
        fields: ['parent'],
        filters: { supplier: supplier, parenttype: 'Item' },
        limit_page_length: 0
    });

    Promise.all([by_field, by_table]).then(([a, b]) => {
        // ignore the answer if the supplier was changed meanwhile
        if (frm.doc.supplier !== supplier) return;

        const names = new Set();
        (a || []).forEach(d => names.add(d.name));
        (b || []).forEach(d => names.add(d.parent));

        frm._supplier_items = [...names];
        set_supplier_item_query(frm);
    });
}

function set_supplier_item_query(frm) {
    frm.set_query('item_code', 'items', function () {
        const filters = { is_purchase_item: 1 };

        if (frm.doc.supplier && frm._supplier_items) {
            // an empty list must match nothing, so use a name that cannot exist
            filters.name = ['in', frm._supplier_items.length ? frm._supplier_items : ['']];
        }

        return {
            query: 'erpnext.controllers.queries.item_query',
            filters: filters
        };
    });
}

