// Client Script  |  DocType: Stock Entry  |  View: Form  |  Enabled
// Box Unpacking: pick the racks the box is taken from; the Items table and the
// storage-location table are filled automatically.

const BU_TYPE = 'Box Unpacking';
const BU_QTY = 'quantity';                            // qty field on Item > Storage Location rows
const BU_STORAGE_TABLE = 'custom_storage_location';   // table on Item AND on Stock Entry
const BU_BOX_TABLE = 'custom_box_items';              // Item > Inside Items
const BU_BOX_ITEM = 'item';                           // field in Inside Items row
const BU_BOX_QTY = 'quantity';                        // field in Inside Items row

frappe.ui.form.on('Stock Entry', {
    refresh(frm) {
        bu_toggle_button(frm);
    },
    onload_post_render(frm) {
        bu_toggle_button(frm);
    },
    stock_entry_type(frm) {
        // runs as soon as the type is selected (no save needed)
        bu_toggle_button(frm);
    }
});

function bu_toggle_button(frm) {
    frm.remove_custom_button(__('Unpack Box'));
    if (frm.doc.stock_entry_type === BU_TYPE && frm.doc.docstatus === 0) {
        frm.add_custom_button(__('Unpack Box'), () => bu_unpack_box(frm)).addClass('btn-primary');
    }
}

async function bu_unpack_box(frm) {
    if (!frm.doc.custom_box_item) {
        frappe.msgprint(__('Select the Box Item first'));
        return;
    }
    const box_qty = flt(frm.doc.custom_box_qty) || 1;
    const box = await frappe.db.get_doc('Item', frm.doc.custom_box_item);
    const inside = box[BU_BOX_TABLE] || [];

    if (!inside.length) {
        frappe.msgprint(__('{0} has no Inside Items', [box.name]));
        return;
    }

    const racks = (box[BU_STORAGE_TABLE] || []).filter(r => flt(r[BU_QTY]) > 0);
    if (!racks.length) {
        frappe.msgprint(__('No storage location with stock found for {0}', [box.name]));
        return;
    }

    // Pre-fill Unpack Qty from the first racks (editable in the popup)
    let remaining = box_qty;
    const rows = racks.map(r => {
        const take = Math.min(remaining, flt(r[BU_QTY]));
        remaining -= take;
        return {
            warehouse: r.warehouse, floor: r.floor, area: r.area,
            shelf: r.shelf, rack: r.rack,
            available: flt(r[BU_QTY]), take_qty: take
        };
    });

    const d = new frappe.ui.Dialog({
        title: __('Select racks to unpack {0} box(es)', [box_qty]),
        size: 'extra-large',
        fields: [{
            fieldname: 'locations',
            fieldtype: 'Table',
            cannot_add_rows: true,
            cannot_delete_rows: true,
            in_place_edit: true,
            data: rows,
            fields: [
                {fieldname: 'warehouse', fieldtype: 'Data', label: 'Warehouse', in_list_view: 1, read_only: 1, columns: 2},
                {fieldname: 'floor', fieldtype: 'Data', label: 'Floor', in_list_view: 1, read_only: 1, columns: 1},
                {fieldname: 'area', fieldtype: 'Data', label: 'Area', in_list_view: 1, read_only: 1, columns: 1},
                {fieldname: 'shelf', fieldtype: 'Data', label: 'Shelf', in_list_view: 1, read_only: 1, columns: 2},
                {fieldname: 'rack', fieldtype: 'Data', label: 'Rack', in_list_view: 1, read_only: 1, columns: 2},
                {fieldname: 'available', fieldtype: 'Float', label: 'Available', in_list_view: 1, read_only: 1, columns: 1},
                {fieldname: 'take_qty', fieldtype: 'Float', label: 'Unpack Qty', in_list_view: 1, columns: 1}
            ]
        }],
        primary_action_label: __('Apply'),
        async primary_action(values) {
            const picked = (values.locations || []).filter(r => flt(r.take_qty) > 0);
            const total = picked.reduce((a, r) => a + flt(r.take_qty), 0);

            if (total !== box_qty) {
                frappe.msgprint(__('Total Unpack Qty must be {0} (now {1})', [box_qty, total]));
                return;
            }
            if (picked.some(r => flt(r.take_qty) > flt(r.available))) {
                frappe.msgprint(__('Unpack Qty cannot exceed the available quantity'));
                return;
            }
            const whs = [...new Set(picked.map(r => r.warehouse))];
            if (whs.length > 1) {
                frappe.msgprint(__('Racks must be in one warehouse per entry. Make a separate Stock Entry for {0}', [whs.join(', ')]));
                return;
            }
            d.hide();

            const wh = whs[0];
            await frm.set_value('from_warehouse', wh);
            await frm.set_value('to_warehouse', wh);

            // ---------- Items table ----------
            frappe.flags.hide_serial_batch_dialog = true;   // no Serial/Batch popup
            try {
            frm.clear_table('items');

            const r = frm.add_child('items');
            await frappe.model.set_value(r.doctype, r.name, 'item_code', box.name);
            await frappe.model.set_value(r.doctype, r.name, 'qty', box_qty);
            await frappe.model.set_value(r.doctype, r.name, 's_warehouse', wh);
            await frappe.model.set_value(r.doctype, r.name, 't_warehouse', '');

            for (const i of inside) {
                const c = frm.add_child('items');
                await frappe.model.set_value(c.doctype, c.name, 'item_code', i[BU_BOX_ITEM]);
                await frappe.model.set_value(c.doctype, c.name, 'qty', flt(i[BU_BOX_QTY]) * box_qty);
                await frappe.model.set_value(c.doctype, c.name, 's_warehouse', '');
                await frappe.model.set_value(c.doctype, c.name, 't_warehouse', wh);
            }
            frm.refresh_field('items');
            } finally {
                frappe.flags.hide_serial_batch_dialog = false;
            }

            // ---------- Storage table ----------
            frm.clear_table(BU_STORAGE_TABLE);
            picked.forEach(p => {
                // box leaves this rack
                const b = frm.add_child(BU_STORAGE_TABLE);
                Object.assign(b, {
                    item: box.name, warehouse: p.warehouse, floor: p.floor, area: p.area,
                    shelf: p.shelf, rack: p.rack, uom: box.stock_uom, [BU_QTY]: flt(p.take_qty)
                });
                // inside items: default = same rack (edit these rows to use a different shelf/rack)
                inside.forEach(i => {
                    const c = frm.add_child(BU_STORAGE_TABLE);
                    Object.assign(c, {
                        item: i[BU_BOX_ITEM], warehouse: p.warehouse, floor: p.floor, area: p.area,
                        shelf: p.shelf, rack: p.rack, uom: i.uom,
                        [BU_QTY]: flt(i[BU_BOX_QTY]) * flt(p.take_qty)
                    });
                });
            });
            frm.refresh_field(BU_STORAGE_TABLE);
        }
    });
    d.show();
}

// find a field by its fieldname, or else by its label
function find_df(frm, fieldname, label) {
  const fields = frm.meta.fields || [];
  return fields.find(f => f.fieldname === fieldname)
      || fields.find(f => (f.label || '').trim().toLowerCase() === label);
}

// the invoice (and the row) this new Box Entry was started from
function get_source() {
  const link = frappe._from_link;
  if (link && link.frm && link.frm.doctype === 'Purchase Invoice') {
    return { invoice: link.frm.doc, row: link.doc || {} };
  }

  // fallback: the page we came from was a Purchase Invoice
  const prev = frappe.get_prev_route ? frappe.get_prev_route() : [];
  if (prev[0] === 'Form' && prev[1] === 'Purchase Invoice'
      && locals['Purchase Invoice'] && locals['Purchase Invoice'][prev[2]]) {
    const invoice = locals['Purchase Invoice'][prev[2]];
    const codes = [...new Set((invoice.items || []).map(r => r.item_code).filter(Boolean))];
    return { invoice, row: { item_code: codes.length === 1 ? codes[0] : '' } };
  }
  return null;
}

function autofill_from_invoice(frm) {
  if (!frm.is_new() || frm._autofilled_for === frm.doc.name) return;

  const src = get_source();
  if (!src) return;
  frm._autofilled_for = frm.doc.name;

  const { invoice, row } = src;

  const supplier_df = find_df(frm, 'supplier', 'supplier');
  if (supplier_df && invoice.supplier && !frm.doc[supplier_df.fieldname]) {
    frm.set_value(supplier_df.fieldname, invoice.supplier);
  }

  const vehicle_df = find_df(frm, 'vehicle', 'vehicle');
  if (vehicle_df && row.item_code && !frm.doc[vehicle_df.fieldname]) {
    if (vehicle_df.fieldtype === 'Link' && vehicle_df.options !== 'Item') {
      frappe.show_alert({
        message: __('Vehicle links to {0}, so it was not filled', [vehicle_df.options]),
        indicator: 'orange',
      });
    } else {
      frm.set_value(vehicle_df.fieldname, row.item_code);
    }
  }
}

frappe.ui.form.on('Box Entry', {
  onload_post_render(frm) { autofill_from_invoice(frm); },
  refresh(frm) { autofill_from_invoice(frm); },
});

// fill Supplier and Vehicle of a Box Entry from this invoice and the item row
async function fill_box_entry(frm, row) {
  const box = row.custom_box_barcode;           // the Box Name cell holds the Box Entry
  if (!box) return;

  await frappe.model.with_doctype('Box Entry');
  const meta = frappe.get_meta('Box Entry');
  const find = (name) => (meta.fields || []).find(
    f => f.fieldname === name || (f.label || '').trim().toLowerCase() === name
  );
  const supplier_df = find('supplier');
  const vehicle_df = find('vehicle');

  const wanted = {};
  if (supplier_df && frm.doc.supplier) wanted[supplier_df.fieldname] = frm.doc.supplier;

  if (vehicle_df && row.item_code) {
    if (vehicle_df.fieldtype === 'Link' && vehicle_df.options !== 'Item') {
      frappe.show_alert({
        message: __('Vehicle links to {0}, so it was not filled', [vehicle_df.options]),
        indicator: 'orange',
      });
    } else {
      wanted[vehicle_df.fieldname] = row.item_code;
    }
  }

  const fields = Object.keys(wanted);
  console.log('Box Entry autofill:', box, wanted);
  if (!fields.length) return;

  const r = await frappe.db.get_value('Box Entry', box, fields);
  const current = (r && r.message) || {};

  const update = {};
  fields.forEach(f => { if (!current[f]) update[f] = wanted[f]; });
  if (!Object.keys(update).length) return;

  await frappe.db.set_value('Box Entry', box, update);
  frappe.show_alert({ message: __('Box Entry {0} updated', [box]), indicator: 'green' });
}

frappe.ui.form.on('Purchase Invoice Item', {
