// When an Item is picked in a popup row, fill that row's UOM with the item's stock UOM.
function fetch_uom_for_row(control) {
    const grid_row = control.grid_row;
    const row = control.doc || (grid_row && grid_row.doc);
    const item = control.get_value ? control.get_value() : row && row.item;
    if (!row || !item) return;

    frappe.db.get_value("Item", item, "stock_uom").then((r) => {
        const uom = r && r.message && r.message.stock_uom;
        if (!uom) return;
        row.uom = uom;
        if (grid_row && grid_row.refresh_field) {
            grid_row.refresh_field("uom");
        } else if (control.grid) {
            control.grid.refresh();
        }
    });
}

