// ---- settings -------------------------------------------------------------
const BOX_ENTRY_TABLE = 'custom_box_entry';     // table field on Purchase Invoice
const BOX_ENTRY_ITEM = 'item';                  // Item field of the Box Entry table
const BOX_ENTRY_COUNT = 'box_count';            // Box Count field of the Box Entry table
const BOX_ENTRY_REQUIRED = 'box_required';      // Box Required field of the Box Entry table
const NEEDED = 'Needed';                        // Box Required value when boxes are needed
const BOX_NAME_FIELD = 'custom_box_name';       // item row field labelled "Box Name" (links to Box Entry)
const BOX_BARCODE_FIELD = 'custom_box_code';    // optional item row field "Box Barcode" (column stays empty without it)
const BOX_RATE_MODE = 'equal';                  // 'equal' = rate split over the box rows
                                                // 'first_box' = all payment on the first box row
const F = { vehicle: 'custom_vehicle_type', price_list: 'custom_price_list' };

// child DocType of the Box Entry table (read from the form, fallback below)
const _entry_df = ((frappe.get_meta('Purchase Invoice') || {}).fields || [])
  .find(f => f.fieldname === BOX_ENTRY_TABLE);
const BOX_ENTRY_DT = (_entry_df && _entry_df.options) || 'Purchase Invoice Box Entry';

// fields that must not be copied to a new box row
const BOX_SKIP = new Set([
  'name', 'idx', 'doctype', 'docstatus', 'parent', 'parentfield', 'parenttype',
  'owner', 'creation', 'modified', 'modified_by',
  'amount', 'base_amount', 'net_amount', 'base_net_amount', 'net_rate', 'base_net_rate',
  'base_rate', 'base_price_list_rate', 'stock_qty', 'received_qty', 'rejected_qty',
  'custom_tax_amount', 'custom_net_amount_with_tax',
  'custom_box_of', BOX_NAME_FIELD, BOX_BARCODE_FIELD,
]);

const item_codes = (doc) => [...new Set((doc.items || []).map(r => r.item_code).filter(Boolean))];
const rows_of = (doc, code) => (doc.items || []).filter(r => r.item_code === code);
const set = (row, field, value) => frappe.model.set_value(row.doctype, row.name, field, value);

// how many box rows an item should have: 0 unless Box Required = Needed
const box_target = (frm, code) => {
  const e = (frm.doc[BOX_ENTRY_TABLE] || []).find(x => x[BOX_ENTRY_ITEM] === code);
  if (!e || (e[BOX_ENTRY_REQUIRED] || NEEDED) !== NEEDED) return 0;
  return Math.max(cint(e[BOX_ENTRY_COUNT]), 0);
};

// Needed: every row of the item is a box row. Not Needed: one normal row.
function group_info(rows, n) {
  return { main: rows[0], boxes: n > 0 ? rows : [] };
}

// ---- events ---------------------------------------------------------------
function on_box_entry_change(frm) {
  sync_box_rows(frm);
  ensure_box_of(frm);
  lock_rows(frm);
}

frappe.ui.form.on('Purchase Invoice', {
  setup(frm) {
    frm.set_query(BOX_ENTRY_ITEM, BOX_ENTRY_TABLE, (doc) => ({
      filters: { name: ['in', item_codes(doc)] },
    }));
  },
  refresh(frm) {
    if (frm.doc.docstatus === 0) { sync_box_entry(frm); ensure_box_of(frm); lock_rows(frm); }
    render_pi_table(frm);
  },
  validate(frm) { sync_box_rows(frm); ensure_box_of(frm); },
  after_save(frm) { lock_rows(frm); render_pi_table(frm); },
  conversion_rate(frm) { render_pi_table(frm); },
});

const box_entry_events = {};
box_entry_events[BOX_ENTRY_COUNT] = on_box_entry_change;
box_entry_events[BOX_ENTRY_REQUIRED] = on_box_entry_change;
box_entry_events[BOX_ENTRY_ITEM] = on_box_entry_change;
frappe.ui.form.on(BOX_ENTRY_DT, box_entry_events);

frappe.ui.form.on('Purchase Invoice Item', {
  item_code(frm) { sync_box_entry(frm); ensure_box_of(frm); lock_rows(frm); render_pi_table(frm); },
  items_add(frm) { sync_box_entry(frm); lock_rows(frm); render_pi_table(frm); },
  items_remove(frm) { sync_box_entry(frm); render_pi_table(frm); },
  qty(frm, cdt, cdn) {
    // for a Needed item, all box rows carry the same quantity
    const row = locals[cdt][cdn];
    if (box_target(frm, row.item_code) > 0) {
      (frm.doc.items || [])
        .filter(r => r !== row && r.item_code === row.item_code && flt(r.qty) !== flt(row.qty))
        .forEach(r => set(r, 'qty', row.qty));
    }
    render_pi_table(frm);
  },
  rate: (frm) => render_pi_table(frm),
  custom_box_name: (frm) => render_pi_table(frm),
});

// ---- Box Of: only box rows carry the item --------------------------------
function ensure_box_of(frm) {
  let changed = false;
  const upd = (r, v) => {
    if ((r.custom_box_of || '') !== v) { r.custom_box_of = v; changed = true; }
  };
  item_codes(frm.doc).forEach(code => {
    const n = box_target(frm, code);
    rows_of(frm.doc, code).forEach(r => upd(r, n > 0 ? code : ''));
  });
  if (changed) frm.refresh_field('items');
}

// ---- Box Name is editable on box rows only ---------------------------------
function lock_rows(frm) {
  clearTimeout(frm._lock_t);
  frm._lock_t = setTimeout(() => {
    if (frm.doc.docstatus !== 0) return;
    item_codes(frm.doc).forEach(code => {
      const is_box = box_target(frm, code) > 0;
      rows_of(frm.doc, code).forEach(r => {
        frm.set_df_property(BOX_NAME_FIELD, 'read_only', is_box ? 0 : 1, r.name, 'items');
      });
    });
  }, 400);
}

// ---- Box Entry: one row per item of the invoice ---------------------------
function sync_box_entry(frm) {
  if (frm.doc.docstatus !== 0) return;
  const entries = () => frm.doc[BOX_ENTRY_TABLE] || [];
  let changed = false;

  item_codes(frm.doc).forEach(code => {
    if (entries().some(e => e[BOX_ENTRY_ITEM] === code)) return;
    let e = entries().find(x => !x[BOX_ENTRY_ITEM]);      // reuse the empty row
    if (!e) e = frm.add_child(BOX_ENTRY_TABLE);
    e[BOX_ENTRY_ITEM] = code;
    changed = true;
  });

  if (changed) {
    frm.refresh_field(BOX_ENTRY_TABLE);
    frm.dirty();
  }
}

// ---- Box Required / Box Count -> one row per box --------------------------
function split_rate(total, n, prec) {
  total = flt(total);
  if (!n) return [];
  if (BOX_RATE_MODE === 'first_box') {
    return Array.from({ length: n }, (_, i) => (i === 0 ? total : 0));
  }
  const base = flt(total / n, prec);
  const rates = Array(n).fill(base);
  rates[n - 1] = flt(total - base * (n - 1), prec);   // last box takes the rounding
  return rates;
}

function reorder_items(frm) {
  const order = [];
  const groups = {};
  (frm.doc.items || []).forEach(r => {
    const k = r.item_code || '';
    if (!(k in groups)) { groups[k] = []; order.push(k); }
    groups[k].push(r);
  });
  const out = [];
  order.forEach(k => out.push(...groups[k]));          // rows of one item stay together
  out.forEach((r, i) => { r.idx = i + 1; });
  frm.doc.items = out;
}

function sync_box_rows(frm) {
  if (frm.doc.docstatus !== 0) return;
  let changed = false;

  (frm.doc[BOX_ENTRY_TABLE] || []).forEach(e => {
    const code = e[BOX_ENTRY_ITEM];
    if (!code) return;
    const n = box_target(frm, code);
    const target = Math.max(n, 1);                      // Not Needed (or no count yet): one normal row
    const rows = rows_of(frm.doc, code);
    if (!rows.length || rows.length === target) return;

    const first = rows[0];
    // price of one unit = sum of the rates of its rows (one row: its own rate)
    const unit_rate = rows.reduce((a, r) => a + flt(r.rate), 0);
    const unit_plr = rows.reduce((a, r) => a + flt(r.price_list_rate), 0);

    const keep = rows.slice();
    if (target > keep.length) {
      for (let i = keep.length; i < target; i++) {
        const row = frm.add_child('items');
        Object.keys(first).forEach(k => {
          if (!BOX_SKIP.has(k) && k.indexOf('__') !== 0) row[k] = first[k];
        });
        row[BOX_NAME_FIELD] = '';
        row[BOX_BARCODE_FIELD] = '';
        keep.push(row);
      }
    } else {
      const drop = keep.splice(target);
      frm.doc.items = frm.doc.items.filter(r => !drop.includes(r));
    }

    const prec = precision('rate', first) || 2;
    const rates = split_rate(unit_rate, keep.length, prec);
    const plrs = split_rate(unit_plr, keep.length, prec);

    keep.forEach((r, i) => {
      set(r, 'qty', first.qty);
      set(r, 'price_list_rate', plrs[i]);
      set(r, 'rate', rates[i]);
      set(r, 'custom_box_of', n > 0 ? code : '');
      if (n === 0) r[BOX_NAME_FIELD] = '';
    });
    changed = true;
  });

  if (changed) {
    reorder_items(frm);
    frm.refresh_field('items');
    if (frm.cscript && frm.cscript.calculate_taxes_and_totals) {
      frm.cscript.calculate_taxes_and_totals();
    }
    lock_rows(frm);
    render_pi_table(frm);
  }
}

// ---- Items / Packaging Details table -------------------------------------
function render_pi_table(frm) {
  clearTimeout(frm._render_t);
  frm._render_t = setTimeout(async () => {
    const wrap = frm.fields_dict.custom_item_details;
    if (!wrap) return;

    const codes = item_codes(frm.doc);
    let info = {};
    if (codes.length) {
      const r = await frappe.call({
        method: 'byky_app.item_tax.get_item_details',
        args: { item_codes: codes },
      });
      info = r.message || {};
    }

    const cur = frm.doc.currency || '';
    const base = erpnext.get_currency(frm.doc.company) || '';
    const cr = flt(frm.doc.conversion_rate) || 1;
    const fmt = (v) => format_number(v, null, 2);
    const esc = (v) => frappe.utils.escape_html(v || '');
    const tot = { qty: 0, tx: 0, txb: 0, tax: 0, taxb: 0, net: 0, netb: 0, boxes: 0 };

    const box_cells = (b) => {
      if (!b) return '<td></td><td></td><td class="n"></td>';
      tot.boxes += flt(b.qty);
      return `<td>${esc(b[BOX_BARCODE_FIELD])}</td><td>${esc(b[BOX_NAME_FIELD])}</td>
              <td class="n">${flt(b.qty)}</td>`;
    };

    let body = '';
    codes.forEach((code, i) => {
      const rows = rows_of(frm.doc, code);
      const { main, boxes } = group_info(rows, box_target(frm, code));
      const d = info[code] || {};
      const rs = `rowspan="${Math.max(boxes.length, 1)}"`;

      // one unit's price is the sum of its rows' rates (the box rows share it)
      const price = rows.reduce((a, r) => a + flt(r.rate), 0);
      const taxable = rows.reduce((a, r) => a + flt(r.net_amount || r.amount), 0);
      const tax = rows.reduce((a, r) => a + flt(r.custom_tax_amount), 0);
      const net = taxable + tax;

      tot.qty += flt(main.qty);
      tot.tx += taxable;  tot.txb += taxable * cr;
      tot.tax += tax;     tot.taxb += tax * cr;
      tot.net += net;     tot.netb += net * cr;

      body += `<tr>
        <td ${rs}>${i + 1}</td>
        <td ${rs}>${esc(d.hsn)}</td>
        <td ${rs}>${esc(d.country)}</td>
        <td ${rs}>${esc(main[F.vehicle] || main.item_name)}</td>
        <td ${rs} class="n">${flt(main.qty)}</td>
        <td ${rs}>${esc(main.uom)}</td>
        <td ${rs}>${esc(main[F.price_list])}</td>
        <td ${rs} class="n">${fmt(price)}</td>
        <td ${rs} class="n">${fmt(price * cr)}</td>
        <td ${rs} class="n">${fmt(taxable)}</td>
        <td ${rs} class="n">${fmt(taxable * cr)}</td>
        <td ${rs} class="n">${fmt(tax)}</td>
        <td ${rs} class="n">${fmt(tax * cr)}</td>
        <td ${rs} class="n">${fmt(net)}</td>
        <td ${rs} class="n">${fmt(net * cr)}</td>
        ${box_cells(boxes[0])}
      </tr>`;
      boxes.slice(1).forEach(b => { body += `<tr>${box_cells(b)}</tr>`; });
    });

    wrap.$wrapper.html(`
      <style>
        .itd { width:100%; border-collapse:collapse; font-size:12px; }
        .itd th, .itd td { border:1px solid var(--border-color); padding:6px 8px; vertical-align:middle; }
        .itd th { background:var(--subtle-fg); text-align:left; }
        .itd td.n, .itd th.n { text-align:right; }
        .itd tfoot td { font-weight:600; background:var(--subtle-fg); }
        .itd-wrap { overflow-x:auto; }
        .itd-sum { width:auto; min-width:420px; margin-top:12px; }
        .itd-sum .grand td { font-weight:700; color:var(--primary); }
      </style>
      <h5 style="margin:16px 0 4px">Items / Packaging Details</h5>
      <div class="text-muted" style="margin-bottom:8px">1 ${cur} = ${cr} ${base}</div>
      <div class="itd-wrap"><table class="itd">
        <thead><tr>
          <th>No.</th><th>HSN Code</th><th>Country of Origin</th><th>Vehicle Type</th>
          <th class="n">QTY</th><th>UOM</th><th>Price List</th>
          <th class="n">Price (${cur})</th><th class="n">Price (${base})</th>
          <th class="n">Taxable Amount (${cur})</th><th class="n">Taxable Amount (${base})</th>
          <th class="n">Tax Amount (${cur})</th><th class="n">Tax Amount (${base})</th>
          <th class="n">Net Amount (${cur})</th><th class="n">Net Amount (${base})</th>
          <th>Box Barcode</th><th>Box Name</th><th class="n">No Of Box's</th>
        </tr></thead>
        <tbody>${body}</tbody>
        <tfoot><tr>
          <td colspan="4">Total</td><td class="n">${tot.qty}</td><td colspan="3"></td>
          <td class="n">${fmt(tot.tx)}</td><td class="n">${fmt(tot.txb)}</td>
          <td class="n">${fmt(tot.tax)}</td><td class="n">${fmt(tot.taxb)}</td>
          <td class="n">${fmt(tot.net)}</td><td class="n">${fmt(tot.netb)}</td>
          <td colspan="2"></td><td class="n">${tot.boxes}</td>
        </tr></tfoot>
      </table></div>

      <h5 style="margin:16px 0 4px">Summary</h5>
      <table class="itd itd-sum">
        <thead><tr><th>Particulars</th><th class="n">Amount (${cur})</th><th class="n">Amount (${base})</th></tr></thead>
        <tbody>
          <tr><td>Total Taxable Amount</td><td class="n">${fmt(tot.tx)}</td><td class="n">${fmt(tot.txb)}</td></tr>
          <tr><td>Total Tax Amount</td><td class="n">${fmt(tot.tax)}</td><td class="n">${fmt(tot.taxb)}</td></tr>
          <tr class="grand"><td>Grand Total (Net Amount)</td>
              <td class="n">${fmt(tot.net)}</td><td class="n">${fmt(tot.netb)}</td></tr>
        </tbody>
      </table>`);
  }, 300);
}

// ---- settings -------------------------------------------------------------
const WO_TABLE = 'custom_source_warehouse_storage_location';   // table on Work Order
const WO_ITEM_FIELD = 'item';                                  // Item field of that table
const LEVELS = ['warehouse', 'floor', 'area', 'shelf', 'rack'];// fieldnames of the location columns
const CLEAR_DOWNSTREAM = true;          // clear Floor, Area, ... when a higher level changes
const POPUP_AS_ALERT = false;           // true = small corner alert, false = popup message
const ONLY_WHEN_EDITING_GRID = true;    // no popup while another script fills the rows

const FG_TABLE = 'custom_finished_product_storage_location';   // Finished Product Storage Location table
const FG_WAREHOUSE_FIELD = 'warehouse';                        // Warehouse column in that table

// child DocType of the source table (read from the form, fallback below)
const _wo_df = ((frappe.get_meta('Work Order') || {}).fields || [])
  .find(f => f.fieldname === WO_TABLE);
const WO_TABLE_DT = (_wo_df && _wo_df.options) || 'Work Order Storage Location';

frappe.ui.form.on('Work Order', {
  setup(frm) {
    LEVELS.forEach((field, i) => {
      frm.set_query(field, WO_TABLE, (doc, cdt, cdn) => {
        const row = locals[cdt][cdn];
        const filters = { item: row[WO_ITEM_FIELD], field };
        LEVELS.slice(0, i).forEach(f => { filters[f] = row[f]; });   // the levels above
        return { query: 'byky_app.storage_query.item_location_query', filters };
      });
    });
  },

  // Target Warehouse changed: update every row in the finished product table
  fg_warehouse(frm) {
    set_fg_storage_warehouse(frm, true);
  },

  // Form opened: fill only the finished product rows that are still empty
  refresh(frm) {
    if (frm.doc.docstatus === 0) {
      set_fg_storage_warehouse(frm, false);
    }
  },

  // New row added to the finished product table: fill it automatically
  [FG_TABLE + '_add'](frm, cdt, cdn) {
    if (frm.doc.fg_warehouse) {
      frappe.model.set_value(cdt, cdn, FG_WAREHOUSE_FIELD, frm.doc.fg_warehouse);
    }
  },
});

// ---- finished product warehouse autofill ----------------------------------
function set_fg_storage_warehouse(frm, overwrite) {
  if (!frm.doc.fg_warehouse) return;

  let changed = false;
  (frm.doc[FG_TABLE] || []).forEach((row) => {
    if (overwrite || !row[FG_WAREHOUSE_FIELD]) {
      frappe.model.set_value(row.doctype, row.name, FG_WAREHOUSE_FIELD, frm.doc.fg_warehouse);
      changed = true;
    }
  });

  if (changed) {
    frm.refresh_field(FG_TABLE);
  }
}

// ---- popup with the quantity saved in the item's Storage Location row ------
async function show_quantity(cdt, cdn, field) {
  const row = locals[cdt][cdn];
  const item = row[WO_ITEM_FIELD];
  if (!item || !row[field]) return;

  // only when the user is working in the grid (not while a script fills the rows)
  if (ONLY_WHEN_EDITING_GRID) {
    const active = document.activeElement;
    if (!active || !active.closest || !active.closest('.grid-row')) return;
  }

  const i = LEVELS.indexOf(field);
  const location = {};
  LEVELS.slice(0, i + 1).forEach(f => { location[f] = row[f]; });

  const r = await frappe.call({
    method: 'byky_app.storage_query.get_location_quantity',
    args: { item, location: JSON.stringify(location) },
  });
  const res = r.message || {};
  if (!res.rows) return;

  // wait until the choice points to one storage row (or the last level is picked)
  if (res.rows > 1 && field !== LEVELS[LEVELS.length - 1]) return;

  const where = LEVELS.slice(0, i + 1).map(f => row[f]).filter(Boolean).join(' / ');
  const qty = res.has_quantity_field
    ? `<b>${format_number(res.quantity, null, 2)}</b>`
    : __('no quantity column found in the Item Storage Location table');

  const message = `<b>${frappe.utils.escape_html(item)}</b><br>`
    + `${frappe.utils.escape_html(where)}<br>`
    + `${__('Quantity saved')}: ${qty}`;

  if (POPUP_AS_ALERT) {
    frappe.show_alert({ message, indicator: 'blue' }, 8);
  } else {
    const frm = cur_frm;
    const reopen_row = () => {
      // wait for the dialog to finish closing, then open the same row again
      setTimeout(() => {
        try {
          const grid = frm.fields_dict[WO_TABLE].grid;
          const grid_row = grid.grid_rows_by_docname[cdn];
          if (grid_row && !grid_row.wrapper.hasClass('grid-row-open')) {
            grid_row.toggle_view(true);
          }
        } catch (e) { console.warn('Could not reopen row', e); }
      }, 150);
    };

    const d = new frappe.ui.Dialog({
      title: __('Available quantity'),
      indicator: 'blue',
      fields: [{ fieldtype: 'HTML', fieldname: 'info', options: message }],
      primary_action_label: __('Close'),
      primary_action() { d.hide(); },
      on_hide: reopen_row,      // runs on Close, the X button, ESC or clicking outside
    });
    d.show();
  }
}

// ---- which grid field is the user typing in right now? ---------------------
function active_grid_field() {
  const a = document.activeElement;
  const w = a && a.closest ? a.closest('[data-fieldname]') : null;
  return w ? w.getAttribute('data-fieldname') : null;
}

// ---- row events (source warehouse storage location table) ------------------
const row_events = {};
LEVELS.forEach((field, i) => {
  row_events[field] = (frm, cdt, cdn) => {
    // ignore changes made by a script (e.g. parents filled after picking a rack)
    if (active_grid_field() !== field) return;

    const row = locals[cdt][cdn];
    if (CLEAR_DOWNSTREAM) {
      LEVELS.slice(i + 1).forEach(next => {
        if (row[next]) frappe.model.set_value(cdt, cdn, next, '');   // levels below start again
      });
    }
    // small delay so the parent levels are filled before the quantity is looked up
    setTimeout(() => show_quantity(cdt, cdn, field), 300);
  };
});

// a new item in the row clears the whole location
row_events[WO_ITEM_FIELD] = (frm, cdt, cdn) => {
  if (active_grid_field() !== WO_ITEM_FIELD) return;
  const row = locals[cdt][cdn];
  LEVELS.forEach(f => { if (row[f]) frappe.model.set_value(cdt, cdn, f, ''); });
};

frappe.ui.form.on(WO_TABLE_DT, row_events);

