const TABLE  = 'custom_source_warehouse_storage_location';
const ITEM   = 'item';
const QTY    = 'quantity';          // check fieldname
const FILLED = ['warehouse'];       // rows with any of these filled are never deleted

const _df   = (frappe.get_meta('Work Order').fields || []).find(f => f.fieldname === TABLE);
const CHILD = _df && _df.options;

frappe.ui.form.on('Work Order', {
    refresh(frm) {
        frm._old_qty = {};
        (frm.doc[TABLE] || []).forEach(r => { frm._old_qty[r.name] = flt(r[QTY] || 1); });
    }
});

if (CHILD) {
    frappe.ui.form.on(CHILD, {
        [QTY](frm, cdt, cdn) {
            frm._old_qty = frm._old_qty || {};
            const row  = locals[cdt][cdn];
            const oldQ = flt(frm._old_qty[row.name] ?? 1);
            const newQ = flt(row[QTY]);
            if (newQ === oldQ) return;

            const grid = frm.fields_dict[TABLE].grid;
            const refresh_cell = () => {
                const gr = grid.grid_rows_by_docname[row.name];
                if (gr) gr.refresh_field(QTY);
            };
            let rows_changed = false;

            if (newQ < 1) { row[QTY] = oldQ; refresh_cell(); return; }

            let delta = newQ - oldQ;
            if (delta > 0) {
                const blanks = (frm.doc[TABLE] || [])
                    .filter(r => r.name !== row.name && r[ITEM] === row[ITEM] && FILLED.every(f => !r[f]))
                    .reverse();
                for (const r of blanks) {
                    if (delta <= 0) break;
                    const q = flt(r[QTY] || 1);
                    if (q <= delta) {
                        delta -= q;
                        delete frm._old_qty[r.name];
                        frappe.model.clear_doc(r.doctype, r.name);
                    } else {
                        r[QTY] = q - delta;
                        frm._old_qty[r.name] = r[QTY];
                        delta = 0;
                    }
                    rows_changed = true;
                }
                if (delta > 0) {
                    row[QTY] = newQ - delta;
                    frappe.show_alert({ message: __('Maximum quantity reached for {0}', [row[ITEM]]), indicator: 'orange' });
                }
            } else {
                for (let i = 0; i < -delta; i++) {
                    const nr = frm.add_child(TABLE);
                    nr[ITEM] = row[ITEM];
                    nr[QTY]  = 1;
                    frm._old_qty[nr.name] = 1;
                    rows_changed = true;
                }
            }

            frm._old_qty[row.name] = flt(row[QTY]);
            if (rows_changed) frm.refresh_field(TABLE); else refresh_cell();
        }
    });
}

// ---- settings -------------------------------------------------------------
const TABLE  = 'custom_finished_item_storage';
const FILLED = ['warehouse'];     // a row with any of these filled is never deleted

// ---- find child doctype and fieldnames automatically -----------------------
const _df   = (frappe.get_meta('Stock Entry').fields || []).find(f => f.fieldname === TABLE);
const CHILD = _df && _df.options;

const _cf  = CHILD ? (frappe.get_meta(CHILD).fields || []) : [];
const pick = (label, fallback) => {
    const f = _cf.find(x => (x.label || '').trim().toLowerCase() === label);
    return f ? f.fieldname : fallback;
};
const ITEM = pick('item', 'item');
const QTY  = pick('quantity', 'qty');
const UOM  = pick('uom', 'uom');

console.log('Finished Item Storage sync:', { CHILD, ITEM, QTY, UOM });

// a blank quantity counts as 1 (one row = one unit)
const q_of = r => flt(r[QTY]) || 1;

frappe.ui.form.on('Stock Entry', {
    refresh(frm) {
        frm._fin_old_qty = {};
        (frm.doc[TABLE] || []).forEach(r => { frm._fin_old_qty[r.name] = q_of(r); });
    }
});

if (CHILD) {
    frappe.ui.form.on(CHILD, {
        [QTY](frm, cdt, cdn) {
            frm._fin_old_qty = frm._fin_old_qty || {};
            const row  = locals[cdt][cdn];
            const oldQ = flt(frm._fin_old_qty[row.name] ?? 1);
            const newQ = flt(row[QTY]);

            if (newQ === oldQ) return;

            const grid = frm.fields_dict[TABLE].grid;
            const refresh_cell = () => {
                const gr = grid.grid_rows_by_docname[row.name];
                if (gr) gr.refresh_field(QTY);
            };
            let rows_changed = false;

            if (newQ < 1) {                          // 0 or negative not allowed
                row[QTY] = oldQ;
                refresh_cell();
                return;
            }

            let delta = newQ - oldQ;

            if (delta > 0) {
                // quantity increased -> remove blank rows of the same item (from the bottom)
                const blanks = (frm.doc[TABLE] || [])
                    .filter(r => r.name !== row.name
                              && r[ITEM] === row[ITEM]
                              && FILLED.every(f => !r[f]))
                    .reverse();

                for (const r of blanks) {
                    if (delta <= 0) break;
                    const q = q_of(r);
                    if (q <= delta) {
                        delta -= q;
                        delete frm._fin_old_qty[r.name];
                        frappe.model.clear_doc(r.doctype, r.name);
                    } else {
                        r[QTY] = q - delta;
                        frm._fin_old_qty[r.name] = r[QTY];
                        delta = 0;
                    }
                    rows_changed = true;
                }

                if (delta > 0) {                     // no blank rows left -> cap it
                    row[QTY] = newQ - delta;
                    frappe.show_alert({
                        message: __('Maximum quantity reached for {0}', [row[ITEM]]),
                        indicator: 'orange'
                    });
                }
            } else {
                // quantity decreased -> add back one row per unit
                for (let i = 0; i < -delta; i++) {
                    const nr = frm.add_child(TABLE);
                    nr[ITEM] = row[ITEM];
                    nr[UOM]  = row[UOM];
                    frm._fin_old_qty[nr.name] = 1;
                    rows_changed = true;
                }
            }

            frm._fin_old_qty[row.name] = q_of(row);

            if (rows_changed) frm.refresh_field(TABLE);   // only when rows were added or removed
            else refresh_cell();                          // otherwise refresh just this cell
        }
    });
}

